// The private, git-ignored state of one checkout: <repo>/.local. Nothing about a machine, an account or the work in progress is
// committed: it is written here by the user (config.toml) or generated by the tool (telemetry, notes, docs, reports).
//   .local/config.toml      overlay of testing/acceptance.toml (any table) + [hosts.<alias>] ssh/role + [paths]
//   .local/telemetry/       probes of this machine and of the build/test hosts
//   .local/docs/            documents generated from the store: lessons, fleet, measurements, upstreams, layout comparison
//   .local/reports/         reports written by tools/flatten.py and tools/unify.py
import { join } from "node:path";

export type Local = {
  hosts?: Record<string, { ssh: string; role: string }>;
  paths?: { chromium_src?: string; scratch?: string };
  [table: string]: unknown;
};

export const localDir = (root: string) => join(root, ".local");

/** The private configuration, or nothing when the file is absent. */
export async function readLocal(root: string): Promise<Local> {
  const file = Bun.file(join(localDir(root), "config.toml"));
  return (await file.exists()) ? (Bun.TOML.parse(await file.text()) as Local) : {};
}

const plain = (x: unknown): x is Record<string, unknown> => !!x && typeof x === "object" && !Array.isArray(x);

/** `over` laid over `base`: tables merge, everything else (arrays included) is replaced. */
export function merge<T>(base: T, over: unknown): T {
  if (!plain(base) || !plain(over)) return (over === undefined ? base : over) as T;
  const out: Record<string, unknown> = { ...base };
  for (const [key, value] of Object.entries(over)) out[key] = key in out ? merge(out[key], value) : value;
  return out as T;
}
